"""InventoryService: receiving and reserving stock."""

import pytest

from inventory.repository import InMemoryStockRepository
from inventory.service import InventoryService, OutOfStock


@pytest.fixture
def service():
    repository = InMemoryStockRepository()
    repository.seed({"SKU-1": 10, "SKU-2": 0})
    return InventoryService(repository)


def test_receive_adds_to_what_is_on_hand(service):
    assert service.receive("SKU-1", 5).on_hand == 15


def test_receive_refuses_an_empty_delivery(service):
    with pytest.raises(ValueError):
        service.receive("SKU-1", 0)


def test_reserve_holds_units(service):
    service.reserve("order-7", "SKU-1", 4)
    assert service.level("SKU-1").available == 6


def test_reserve_refuses_more_than_available(service):
    with pytest.raises(OutOfStock) as caught:
        service.reserve("order-8", "SKU-2", 1)
    assert caught.value.available == 0


def test_release_gives_back_what_an_order_held(service):
    service.reserve("order-9", "SKU-1", 3)
    assert service.release("order-9") == 3
    assert service.level("SKU-1").available == 10

