"""HTTP routes of the inventory service."""

from __future__ import annotations

from fastapi import APIRouter, Depends, HTTPException
from pydantic import BaseModel, Field

from .dependencies import inventory_service
from .service import InventoryService, OutOfStock

router = APIRouter(prefix="/v1/stock", tags=["stock"])


class StockOut(BaseModel):
    sku: str
    on_hand: int
    reserved: int
    available: int


class DeliveryIn(BaseModel):
    quantity: int = Field(gt=0)


@router.get("/{sku}", response_model=StockOut)
def get_level(sku: str, service: InventoryService = Depends(inventory_service)):
    level = service.level(sku)
    return StockOut(
        sku=level.sku,
        on_hand=level.on_hand,
        reserved=level.reserved,
        available=level.available,
    )


@router.post("/{sku}/deliveries", response_model=StockOut)
def receive(
    sku: str,
    delivery: DeliveryIn,
    service: InventoryService = Depends(inventory_service),
):
    level = service.receive(sku, delivery.quantity)
    return StockOut(
        sku=level.sku,
        on_hand=level.on_hand,
        reserved=level.reserved,
        available=level.available,
    )


class ReservationIn(BaseModel):
    order_id: str = Field(min_length=1)
    quantity: int = Field(gt=0)


@router.post("/{sku}/reservations", status_code=201)
def reserve(
    sku: str,
    body: ReservationIn,
    service: InventoryService = Depends(inventory_service),
):
    try:
        reservation = service.reserve(body.order_id, sku, body.quantity)
    except OutOfStock as error:
        raise HTTPException(status_code=409, detail=str(error)) from error
    return {"order_id": reservation.order_id, "quantity": reservation.quantity}
